import java.io.*;import java.net.*;import java.nio.file.*;import java.util.*;
public class DeckRevealCheck {
 static byte[] call(GunnyServer s,GunnyServer.Session u)throws Exception{var b=new ByteArrayOutputStream();DeckReveal.handle(s,u,new DataOutputStream(b));return b.toByteArray();}
 public static void main(String[] a)throws Exception{var store=new CloudStore.Memory();var u=Expansion780Check.session(store,"Deck",20);try(var s=new GunnyServer(new InetSocketAddress("127.0.0.1",0),Path.of("backend/assets"),store)){s.clock.shutdownNow();var r=s.new Room(u,0,0,-1);u.room=r.id;s.rooms.put(r.id,r);r.start();r.phase=2;r.battle.over=true;r.battle.winner=0;r.settled=true;u.cardsReady=true;u.resultAck=r.battle.turn;if(call(s,u)[0]!=0)throw new AssertionError("Revealed before pick");r.cardPicks.put(u.id,1);r.cardNames[0]=u.profile.name;r.cardCoins[0]=500;int coins=u.profile.coins;byte[] first=call(s,u);if(first[0]!=1||!Arrays.equals(first,call(s,u))||u.profile.coins!=coins)throw new AssertionError("Read only stable deck");if(new DataInputStream(new ByteArrayInputStream(first)).readBoolean()!=true)throw new AssertionError();System.out.println("PASS reveal waits for picks, stays stable, never grants remaining cards");}}
}
